SELECT "EXCH_SPOT", (("orderbook_metrics"->>'best_ask')::real - ("orderbook_metrics"->>'best_bid')::real) / 
             (((("orderbook_metrics"->>'best_ask')::real + ("orderbook_metrics"->>'best_bid')::real) / 2.0)) AS spread_ratio
FROM marketdata ORDER BY spread_ratio DESC LIMIT 10;

